{
  "schema_version": "aicatlog.resources.v1",
  "resources": [
    {"id": "workflow", "kind": "workflow", "path": "workflow.txt", "when": "Plan, implement, validate or hand off project work"},
    {"id": "checkpoint-template", "path": "templates/checkpoint.json", "when": "Record a continuation cursor"}
  ]
}

#!/usr/bin/env sh
repo_root=$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd) || exit 1
exec aicatlog harness check --repo "$repo_root" "$@"
